""" Check if a keyword argument is set to None.

    Parameters
    ----------
    v : str
      value of a keyword argument

    Returns
    -------
    v : None, str
      A value used by the settings dictionary
    """
def key_none(v: Any) -> object {
    if (v.lower() == "none") {
        v = None;
    }
    return v;
}

